			function columnAdd() {
			    var caseList = app.lookup("caseList");
			    // 동적으로 생성한 체크박스 그리드에서 삭제(그리드 초기화)
			    app.lookup("grdList").resetGrid();
			   
			    // 동적으로 생성한 데이터 셋 삭제
			    for(var i = 0; i < caseList.getColumnNames().length; i++){
			        if(caseList.getColumnNames()[i].substr(0,3) == "col"){
			            caseList.deleteColumn(caseList.getColumnNames()[i]);
			        }
			    }
			    
			    var dsDays = app.lookup("dsDays");
			    var dsDaysLen = dsDays.getRowCount();
			    if(dsDaysLen == 0){ // 기존에 저장된 자원제공일자가 없음
			        var dmDetail = app.lookup("dmDetail");
			        var strYmd = dmDetail.getValue("SRVC_PVSN_BGNG_YMD");
			        var endYmd = dmDetail.getValue("SRVC_PVSN_END_YMD");
			        var relSrtMonth = strYmd.substr(4, 2); // 받아온 시작일자의 실제 월
			        var relEndMonth = endYmd.substr(4, 2); // 받아온 종료일자의 실제 월
			        var sysSrtMonth = relSrtMonth - 1; // 시작일자의 시스템 월(날짜 계산이 필요하기에 시스템 월이 필요)
			        var sysEndMonth = relEndMonth - 1; // 종료일자의 시스템 월(날짜 계산이 필요하기에 시스템 월이 필요)
			        
			        var strDate = new Date(strYmd.substr(0, 4), sysSrtMonth, strYmd.substr(6, 2));
			        var endDate = new Date(endYmd.substr(0, 4), sysEndMonth, endYmd.substr(6, 2));
			        while (strDate <= endDate) {
			            var month = strDate.getMonth() + 1;
			            var day = strDate.getDate();
			            var monthDay = month + "/" + day; // header에 표시될 내용
			            grdColumnAdd(monthDay, strDate);
			            strDate.setDate(strDate.getDate() + 1);
			        }
			    } else {  // 기존에 저장된 자원제공일자가 있음
			        var rdb1 = app.lookup("rdb1");
			        var dateList = "";
			        var dsDays = app.lookup("dsDays");
			        for(var i = 0; i < dsDays.getRowCount(); i++){
			            var dsDaysRowData = dsDays.getRowData(i);
			            if(dateList == ""){
			                dateList = dsDaysRowData.USE_YMD;    
			            } else {
			                dateList = dateList + "," +dsDaysRowData.USE_YMD;    
			            }
			        }
			        app.lookup("sipb1").value = dateList;
			        saveGrid("onload");
			    }
			    
			}

			function grdColumnAdd(header, date) {
			    var year = date.getFullYear();
			    var month = new String(date.getMonth()+1);
			    var day = new String(date.getDate());
			    if(month.length == 1){
			        month = "0" + month;
			    }
			    if(day.length == 1){
			        day = "0" + day;
			    }
			    var strDay = year + month + day;
			    var grdList = app.lookup("grdList");
			    var dataSet = grdList.dataSet;
			    
			    var grdCellInd = grdList.header.getCellIndices();
			    var grdColCnt = grdCellInd.length;
			    
			    dataSet.addColumn(new cpr.data.header.DataHeader("col" + strDay));
			    
			    grdList.addColumn({
			        columnLayout: [{
			            width: "100px"
			        }],
			        header: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: grdColCnt,
			                colSpan: 1,
			                rowSpan: 1
			            },
			            configurator: function(configurator) {
			                                   
			                configurator.control = (function() {
			                    var checkBox_1 = new cpr.controls.CheckBox("");
			                    checkBox_1.userAttr("colIdx", String(grdColCnt));
			                    checkBox_1.text = header;
			                    checkBox_1.iconAlign = "right";
			                    checkBox_1.trueValue = "Y";
			                    checkBox_1.falseValue = "N";
			                    checkBox_1.style.css({
			                        "text-align": "center"
			                    });                   
			                    checkBox_1.addEventListener("value-change", 
			                        function onCbx1ValueChange(e){
			                            /** 
			                             * @type cpr.controls.CheckBox
			                             */
			                            var cbxHeader = e.control;
			                            var colIdx = Number(cbxHeader.userAttr("colIdx"));
			                            var vcGrdList = app.lookup("grdList");
			                            var vnRowCnt = vcGrdList.getRowCount();
			                            
			                            for(var i=0; i < vnRowCnt; i++){
			                                app.lookup("grdList").setCellValue(i, colIdx, cbxHeader.value);
			                            }                            
			                        }
			                    );
			                    return checkBox_1;
			                })();                
			            }
			        }],
			        detail: [{
			            constraint: {
			                rowIndex: 0,
			                colIndex: grdColCnt
			            },
			            configurator: function(cell) {
			                cell.columnName = "col" + strDay;
			                cell.control = (function() {
			                    var checkBox_1 = new cpr.controls.CheckBox("");
			                    checkBox_1.trueValue = "Y";
			                    checkBox_1.falseValue = "N";
			                    checkBox_1.style.css({
			                        "text-align": "center"
			                    });
			                    checkBox_1.bind("value").toDataColumn("col" + strDay);
			                    checkBox_1.addEventListener("value-change", 
			                        function onCbx1ValueChange(e){
			                            /** 
			                             * @type cpr.controls.CheckBox
			                             */
			                            var cbx1 = e.control;
			                            var grdList = app.lookup("grdList");
			                            var rowIdx = grdList.getSelectedRowIndex();
			                        }
			                    );
			                    return checkBox_1;
			                })();
			                cell.controlConstraint = {};
			            }
			        }]
			        
			    });
			}

			function setChk(){
			    
			    var caseList = app.lookup("caseList");
			    var dsServiceChek = app.lookup("dsServiceChek");
			    var caseMngNo = ""; // 사례관리번호
			    var caseMngOdrno = ""; // 사례관리차수
			    if(dsServiceChek.getRowCount() > 0){
			        for(var i = 0; i < caseList.getRowCount(); i++){
			            var rowData = caseList.getRowData(i);
			            caseMngNo = rowData.CASE_MNG_NO;
			            caseMngOdrno = rowData.CASE_MNG_ODRNO;
			            for(var j = 0; j < dsServiceChek.getRowCount(); j++){
			                var rowData2 = dsServiceChek.getRowData(j);
			                if(caseMngNo == rowData2.CASE_MNG_NO && caseMngOdrno == rowData2.CASE_MNG_ODRNO){
			                    caseList.setValue(i, "col"+rowData2.USE_YMD, "Y");                    
			                }
			            }
			        }
			    }
			    
			    app.lookup("caseList").setRowStateAll(cpr.data.tabledata.RowState.UNCHANGED);
			    app.lookup("dsDays").setRowStateAll(cpr.data.tabledata.RowState.UNCHANGED);
			    util.Control.redraw(app, "grdList");
			}


			/**
			 * 플로팅 위치 계산
			 */
			function calcFloatPort() {
			    
			    //캘린더가 float되어야 할 위치를 계산
			    var voRootContainer = app.getRootAppInstance().getContainer();
			    var voViewPort = voRootContainer.getViewPortRect();
			    var vcSipb = app.lookup("sipb1");
			    var voOffset = vcSipb.getActualRect();    
			        
			    //아래에 float시킬지 여부
			    var vbIsBottomFloat = true;
			    var vbIsLeftFloat = true;
			    var voFloatPort = {
			        top: "0px",
			        left: "0px"
			    }
			    
			    //캘린더가 아래에 위치해야하는지 여부   
			    vbIsBottomFloat = voOffset.top + voOffset.height + mnCalHeight > voViewPort.height ? (voOffset.top - mnCalHeight < 0 ? true : false) : true;
			    voFloatPort.top = vbIsBottomFloat ? voOffset.top + voOffset.height + "px" : voOffset.top - mnCalHeight + "px";
			    
			    //캘린더가 왼쪽에 위치해야 하는지 여부
			    vbIsLeftFloat = voOffset.left + mnCalWidth > voViewPort.width ? (voOffset.right - mnCalWidth < 0 ? true : false) : true;
			    voFloatPort.left = vbIsLeftFloat ? voOffset.left + "px" : voOffset.right - mnCalWidth + "px";
			    
			    return voFloatPort;
			}

