			/*
			 * 서치 인풋에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onSipb1Click2(e) {
			    var sipb1 = e.control;
			    
			    var voOffset = sipb1.getActualRect();
			    var voFloatPort = calcFloatPort(); // 플로팅될 위치를 계산합니다.
			    
			    // 플로팅 시킬 캘린더 컨트롤을 생성합니다.    
			    var vcCal = new cpr.controls.Calendar("cal");
			    vcCal.selectionType = "multiple"; // 다중선택
			    
			    // blur 이벤트에서 컨트롤 삭제
			    vcCal.addEventListener("blur", onCalBlur);
			    // date-click 이벤트에서 서치인풋에 value 추가
			    vcCal.addEventListener("date-click", onCalDateClick);
			    
			    // 플로팅될 캘린더의 스타일 적용    
			    vcCal.style.css({
			        "position": "absolute",
			        "top": voFloatPort.top,
			        "left": voFloatPort.left,
			        "width": mnCalWidth + "px",
			        "height": mnCalHeight + "px"
			    });
			    
			    // 캘린더 데이터 셋팅
			    if(!ValueUtil.isNull(sipb1.value)){
			        // 기존에 선택된 데이터가 있으면 캘린더에 values 적용
			        var vaValues = sipb1.value.split(",");
			        vcCal.values = vaValues;
			    } else {
			        vcCal.values = [];
			    }
			    
			    // 캘린더 min, max Date 설정
			    var vcRangePicker = app.lookup("dmDetail");
			    var vsStartDate = vcRangePicker.getValue("SRVC_PVSN_BGNG_YMD");
			    var vsEndDate = vcRangePicker.getValue("SRVC_PVSN_END_YMD");
			   
			    if(!ValueUtil.isNull(vsStartDate)) vcCal.minDate = moment(vsStartDate).toDate();
			    if(!ValueUtil.isNull(vsEndDate)) vcCal.maxDate = moment(vsEndDate).toDate();
			            
			    // 캘린더를 플로팅 시킨다
			    app.getRootAppInstance().floatControl(vcCal);
			    vcCal.visible = true; 
			    vcCal.focus(); // 플로팅된 캘린더로 포커스 이동(추후 blur 처리를 통한 visible 처리)
			}


