			/*
			 * "일자 저장" 버튼(btnSave2)에서 click 이벤트 발생 시 호출.
			 * 그리드, 데이터셋에 동적 생성한 데이터 삭제 
			 */
			function delGrid(){
			    var caseList = app.lookup("caseList");
			    // 동적으로 생성한 체크박스 그리드에서 삭제(그리드 초기화)
			    app.lookup("grdList").resetGrid();
			   
			    // 동적으로 생성한 데이터셋 삭제
			    for(var i = 0; i < caseList.getColumnNames().length; i++){
			        if(caseList.getColumnNames()[i].substr(0,3) == "col"){
			            caseList.deleteColumn(caseList.getColumnNames()[i]);
			        }
			    }
			}

			function doSaveDays(){
			    saveGrid("save");
			}

			function saveGrid(gubn){
			    var rdb1 = app.lookup("rdb1");
			    var dmDetail = app.lookup("dmDetail");
			    var dsDays = app.lookup("dsDays");
			    var srvcPvsnNo = dmDetail.getValue("SRVC_PVSN_NO"); // 서비스제공번호
			    var resrceNo = dmDetail.getValue("RESRCE_NO"); // 자원번호
			    dsDays.clearData();
			    if(rdb1.value == "Y"){ // 전일
			        var strYmd = dmDetail.getValue("SRVC_PVSN_BGNG_YMD");
			        var endYmd = dmDetail.getValue("SRVC_PVSN_END_YMD");;
			        var relSrtMonth = strYmd.substr(4, 2); // 받아온 시작일자의 실제 월
			        var relEndMonth = endYmd.substr(4, 2); // 받아온 종료일자의 실제 월
			        var sysSrtMonth = relSrtMonth - 1; // 시작일자의 시스템 월(날짜 계산이 필요하기에 시스템 월이 필요)
			        var sysEndMonth = relEndMonth - 1; // 종료일자의 시스템 월(날짜 계산이 필요하기에 시스템 월이 필요)
			        
			        var strDate = new Date(strYmd.substr(0, 4), sysSrtMonth, strYmd.substr(6, 2));
			        var endDate = new Date(endYmd.substr(0, 4), sysEndMonth, endYmd.substr(6, 2));
			        var tempChang = grpChangYN; // grpChangYN 값을 temp에 담는다 
			        app.lookup("sipb1").value = ""; // chang이벤트가 발생한다
			        grpChangYN = tempChang; // chang이벤트 전의 grpChangYN값으로 복귀
			        while (strDate <= endDate) {
			            var month = strDate.getMonth() + 1;
			            var day = strDate.getDate();
			            var monthDay = month + "/" + day; // header에 표시될 내용
			            grdColumnAdd(monthDay, strDate);
			            
			            var year = strDate.getFullYear();
			            var month = new String(strDate.getMonth()+1);
			            var strDay = new String(strDate.getDate());
			            if(month.length == 1){
			                month = "0" + month;
			            }
			            if(strDay.length == 1){
			                day = "0" + day;
			            }
			            var saveDay = year+month+day;
			            var addData = {"SRVC_PVSN_NO":srvcPvsnNo,"RESRCE_NO":resrceNo, "USE_YMD":saveDay, "CNSLTNT_ID":user_id};
			            dsDays.addRowData(addData);
			            strDate.setDate(strDate.getDate() + 1);
			            
			        }
			    } else { // 일자선택
			        var sipb1 = app.lookup("sipb1");
			        var days = sipb1.value.split(",");
			        for(var i = 0; i < days.length; i++){
			            var month = days[i].substr(4, 2);
			            var strDay = days[i].substr(6, 2);
			            var sysSrtMonth;
			            if(month.substr(0, 1) == "0"){
			                month = month.substr(1, 1); // 07 => 7
			            }
			            sysSrtMonth = month -1;
			            if(strDay.substr(0, 1) == "0"){
			                strDay = strDay.substr(1, 1); // 07 => 7
			            }
			            var monthDay = month + "/" + strDay; // header에 표시될 내용
			            var strDate = new Date(days[i].substr(0, 4), sysSrtMonth, strDay);
			            grdColumnAdd(monthDay, strDate);
			            var addData = {"SRVC_PVSN_NO":srvcPvsnNo,"RESRCE_NO":resrceNo, "USE_YMD":days[i], "CNSLTNT_ID":user_id};
			            dsDays.addRowData(addData);
			        }
			    }
			    
			    if(gubn == "save"){
			        // 저장 서브미션 호출
			        app.lookup("dmParam").setValue("SRVC_PVSN_WHDA_YN", rdb1.value);
			        util.Submit.send(app, "subDaySave", function(pbSuccess) {
			            if (pbSuccess) {
			                util.Msg.alert(app, "INF-M000", "저장 되었습니다!");
			                // 일자 선택이 초기화 안됨. 강제 선택 해제
			                var dsCaseList = app.lookup("caseList");
			                for(var i = 0; i < dsCaseList.getRowCount(); i++){
			                    for(var j = 0; j < dsCaseList.getColumnCount(); j++){
			                        if(dsCaseList.getColumnNames()[j].substr(0,3) == "col"){
			                            dsCaseList.setValue(i, dsCaseList.getColumnNames()[j], "");
			                        }
			                    }
			                }
			                
			            } else {
			                util.Msg.alert(app, "INF-M000", "저장 실패!",null, "미선택");
			            }
			        });
			    } else {
			        util.Submit.send(app, "subChkList", function(pbSuccess) {
			            if (pbSuccess) {
			                setChk();
			                grpChangYN = false;
			            }
			        });
			    }
			    
			}

